package com.nigson.acceptance.notification;
import com.nigson.commerce.notification.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.PrivateWorkload;
import com.nigson.shared.problem.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.junit.jupiter.api.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class NotificationPersistenceTest {
    JdbcTemplate jdbc;NotificationService service;OrderFixture fixture;UUID order;SimpleMeterRegistry metrics;
    @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"notification-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);metrics=new SimpleMeterRegistry();fixture=new OrderFixture(jdbc);order=fixture.order();service=new NotificationService(new JdbcNotificationRepository(jdbc),new PlatformStore(jdbc,manager,Clock.systemUTC(),metrics),new AuditWriter(jdbc,Clock.systemUTC(),metrics),manager,metrics);}
    @AfterEach void cleanup(){if(fixture!=null)fixture.close();}
    PrivateWorkload.Proof proof(String api){return new PrivateWorkload.Proof("nigson-integration","synthetic-integration",PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow(),null);}
    NotificationValues.Delivery delivery(UUID job,String state){return new NotificationValues.Delivery(job,order,state,null);}
    @Test void contextIsCurrentMinimumVerifiedRecipientWithoutSendingOrProfiles(){var result=service.context(proof("API-122"),order);assertThat(result.recipient().partyId()).isEqualTo(fixture.party);assertThat(result.total()).isEqualTo("0.00");assertThat(result.trackingUrl()).isNull();assertThat(result.toString()).doesNotContain("example.invalid");jdbc.update("UPDATE commerce.party SET email_verified=false WHERE id=?",fixture.party);assertThatThrownBy(()->service.context(proof("API-122"),order)).hasMessage("NOT_FOUND");assertThatThrownBy(()->service.context(proof("API-133"),order)).hasMessage("ACCESS_DENIED");}
    @Test void businessJobStateDedupKeepsHistoryAndDoesNotChangeOrderTruth(){UUID job=UUID.randomUUID();for(int i=0;i<5;i++)assertThat(service.delivery(proof("API-133"),delivery(job,"SENT"),"duplicate-"+i,UUID.randomUUID()).acknowledged()).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE operation='API-133-OUTCOME-SENT' AND request_key=?",Integer.class,job.toString())).isEqualTo(1);assertThat(metrics.counter("nigson.notification.outcomes","state","SENT").count()).isEqualTo(1);service.delivery(proof("API-133"),delivery(job,"UNKNOWN"),"late",UUID.randomUUID());assertThat(jdbc.queryForObject("SELECT status FROM commerce.sales_order WHERE id=?",String.class,order)).isEqualTo("PENDING");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='NOTIFICATION_DELIVERY'",Integer.class,order)).isEqualTo(2);
        UUID other=fixture.order();assertThatThrownBy(()->service.delivery(proof("API-133"),new NotificationValues.Delivery(job,other,"FAILED",null),"different-owner",UUID.randomUUID())).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->service.delivery(proof("API-133"),new NotificationValues.Delivery(job,order,"SENT","different-reference"),"different-reference",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");}
    @Test void auditFailureRollsBackBusinessOutcomeThenSameHeaderRecovers(){UUID job=UUID.randomUUID();var admin=new JdbcTemplate(new DriverManagerDataSource(System.getenv("NIGSON_TEST_JDBC_URL"),"nigson_bootstrap","mock-bootstrap"));admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->service.delivery(proof("API-133"),delivery(job,"FAILED"),"audit",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE request_key=?",Integer.class,job.toString())).isZero();}finally{admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(service.delivery(proof("API-133"),delivery(job,"FAILED"),"audit",UUID.randomUUID()).acknowledged()).isTrue();}
    @Test void twelveDifferentCallbackKeysStillProduceOneBusinessOutcome()throws Exception{UUID job=UUID.randomUUID();var start=new CyclicBarrier(12);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<12;i++){String key="race-"+i;futures.add(pool.submit(()->{start.await();for(int n=0;n<20;n++)try{return service.delivery(proof("API-133"),delivery(job,"SUPPRESSED"),key,UUID.randomUUID()).acknowledged();}catch(PlatformStore.Conflict busy){if(!busy.getMessage().equals("IDEMPOTENCY_IN_PROGRESS"))throw busy;Thread.sleep(50);}throw new IllegalStateException("BOUNDED_REPLAY_EXHAUSTED");}));}for(var f:futures)assertThat(f.get(15,TimeUnit.SECONDS)).isTrue();}assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='NOTIFICATION_DELIVERY'",Integer.class,order)).isEqualTo(1);}
}
